import { access } from "node:fs/promises";
import path from "node:path";
import type {
  LoadedPipeline,
  PipelineConfig,
  PipelineStageSource,
} from "../types/pipeline.js";
import type { StageConfig } from "../types/stage.js";
import { loadFailure, loadSuccess, type LoadOutcome } from "./loadOutcome.js";
import { mergePipelineStages } from "./mergePipelineIncludes.js";
import {
  normalizePipelineStageEntries,
  toWiringRefs,
} from "./normalizePipelineStageEntry.js";
import { loadStageFromObjectOutcome, loadStageOutcome } from "./loadStage.js";
import { resolvePipelineDagFromRefs } from "./resolvePipelineDag.js";

export type { LoadedPipeline } from "../types/pipeline.js";
export type { LoadIssue, LoadOutcome } from "./loadOutcome.js";

export async function resolvePipelinePath(
  pipelinePath: string,
  cwd: string,
): Promise<string> {
  const resolved = path.normalize(path.resolve(cwd, pipelinePath));
  try {
    await access(resolved);
    return resolved;
  } catch {
    throw new Error(
      `Pipeline file not found: ${resolved}. Pass a filesystem path to --pipeline (e.g. pipelines/hello.pipeline.yaml), not a bare pipeline id.`,
    );
  }
}

async function loadPipelineFromPath(
  pipelinePath: string,
): Promise<LoadOutcome<LoadedPipeline>> {
  const normalizedPipelinePath = path.normalize(path.resolve(pipelinePath));

  const mergeOutcome = await mergePipelineStages(normalizedPipelinePath);
  if (!mergeOutcome.ok) {
    return loadFailure(mergeOutcome.issues);
  }

  const { entries: rawEntries, pipelineId } = mergeOutcome.value;
  const ctx = { pipelineId, path: normalizedPipelinePath };

  const normalizeOutcome = normalizePipelineStageEntries(rawEntries, ctx);
  if (!normalizeOutcome.ok) {
    return loadFailure(normalizeOutcome.issues);
  }

  const normalizedEntries = normalizeOutcome.value;
  const wiringRefs = toWiringRefs(normalizedEntries);

  let stageIds: string[];
  let dag: LoadedPipeline["dag"];
  try {
    const resolved = resolvePipelineDagFromRefs(wiringRefs, ctx);
    stageIds = resolved.stages;
    dag = resolved.dag;
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    return loadFailure([
      {
        code: "pipeline.dag_error",
        message,
        category: "pipeline",
        pipelineId,
      },
    ]);
  }

  const entryById = new Map(normalizedEntries.map((entry) => [entry.id, entry]));
  const stageSources: Record<string, PipelineStageSource> = {};
  const stages: StageConfig[] = [];

  for (const stageId of stageIds) {
    const entry = entryById.get(stageId);
    if (!entry) {
      return loadFailure([
        {
          code: "pipeline.invalid_shape",
          message: `Pipeline ${pipelineId}: missing normalized entry for stage "${stageId}"`,
          category: "pipeline",
          pipelineId,
        },
      ]);
    }

    if (entry.body.kind === "inline") {
      const inlineOutcome = loadStageFromObjectOutcome(entry.body.raw, {
        entryId: entry.id,
        declaringPath: entry.declaringPath,
      });
      if (!inlineOutcome.ok) {
        return loadFailure(inlineOutcome.issues);
      }
      stages.push(inlineOutcome.value);
      stageSources[stageId] = { kind: "inline" };
      continue;
    }

    const stageOutcome = await loadStageOutcome(entry.body.absolutePath);
    if (!stageOutcome.ok) {
      return loadFailure([
        {
          code: "pipeline.missing_stage",
          message: `Pipeline ${pipelineId} references missing stage "${stageId}" at ${entry.body.absolutePath}`,
          category: "pipeline",
          pipelineId,
        },
        ...stageOutcome.issues,
      ]);
    }

    if (stageOutcome.value.id !== entry.id) {
      return loadFailure([
        {
          code: "pipeline.stage_id_mismatch",
          message: `Pipeline ${pipelineId}: stage entry "${entry.id}" in ${entry.declaringPath} uses ${entry.body.path} which declares id "${stageOutcome.value.id}"`,
          category: "pipeline",
          pipelineId,
        },
      ]);
    }

    const stage: StageConfig = {
      ...stageOutcome.value,
      ...(entry.skill !== undefined ? { skill: entry.skill } : {}),
    };
    stages.push(stage);
    stageSources[stageId] = { kind: "file", path: entry.body.absolutePath };
  }

  const pipeline: PipelineConfig = {
    id: pipelineId,
    stages: stageIds,
  };

  return loadSuccess({
    pipeline,
    stages,
    dag,
    pipelinePath: normalizedPipelinePath,
    stageSources,
  });
}

export async function loadPipelineOutcome(
  nameOrPath: string,
  options: { cwd?: string } = {},
): Promise<LoadOutcome<LoadedPipeline>> {
  const cwd = options.cwd ?? process.cwd();

  let pipelinePath: string;
  try {
    pipelinePath = await resolvePipelinePath(nameOrPath, cwd);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    return loadFailure([
      {
        code: "pipeline.load_error",
        message,
        category: "pipeline",
      },
    ]);
  }

  return loadPipelineFromPath(pipelinePath);
}

export async function loadPipeline(
  nameOrPath: string,
  options: { cwd?: string } = {},
): Promise<LoadedPipeline> {
  const outcome = await loadPipelineOutcome(nameOrPath, options);
  if (!outcome.ok) {
    throw new Error(outcome.issues[0].message);
  }
  return outcome.value;
}

import path from "node:path";
import type { NormalizedPipelineStageEntry } from "../types/pipeline.js";
import { loadFailure, loadSuccess, type LoadOutcome } from "./loadOutcome.js";
import {
  BODY_KEYS,
  isAllowedPipelineStageEntryKey,
} from "./pipelineStageKeys.js";
import type { RawMergedEntry } from "./mergePipelineIncludes.js";

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function inferIdFromUsesPath(usesPath: string): string | null {
  const base = path.basename(usesPath);
  if (!base) return null;
  if (base.endsWith(".stage.yaml")) {
    const id = base.slice(0, -".stage.yaml".length);
    return id || null;
  }
  if (base.endsWith(".yaml")) {
    const id = base.slice(0, -".yaml".length);
    return id || null;
  }
  return base;
}

function extractBodyRaw(raw: Record<string, unknown>): Record<string, unknown> {
  const body: Record<string, unknown> = {};
  for (const key of Object.keys(raw)) {
    if (BODY_KEYS.has(key)) {
      body[key] = raw[key];
    }
  }
  return body;
}

function hasBodyKey(raw: Record<string, unknown>): boolean {
  return Object.keys(raw).some((key) => BODY_KEYS.has(key) && key !== "skill");
}

function readSkill(raw: Record<string, unknown>): LoadOutcome<string> | undefined {
  if (raw.skill === undefined) return undefined;
  if (typeof raw.skill !== "string" || raw.skill.trim() === "") {
    return loadFailure([
      {
        code: "stage.invalid_skill",
        message: "skill must be a non-empty string",
        category: "stage",
      },
    ]);
  }
  return loadSuccess(raw.skill.trim());
}

function stringStageRefMessage(
  index: number,
  declaringPath: string,
  entry: string,
): string {
  const hint = entry
    ? `bare string stage refs are not supported; use { id: "${entry}", uses: "./${entry}.yaml" } or inline body`
    : `bare string stage refs are not supported; use { id: "…", uses: "./….yaml" } or inline body`;
  return `Invalid stage entry at index ${index} in ${declaringPath}: ${hint}`;
}

export function normalizePipelineStageEntries(
  rawEntries: RawMergedEntry[],
  ctx: { pipelineId: string; path: string },
): LoadOutcome<NormalizedPipelineStageEntry[]> {
  const normalized: NormalizedPipelineStageEntry[] = [];

  for (let index = 0; index < rawEntries.length; index++) {
    const { raw, declaringPath } = rawEntries[index];

    if (typeof raw === "string") {
      return loadFailure([
        {
          code: "pipeline.string_stage_ref",
          message: stringStageRefMessage(index, declaringPath, raw),
          category: "pipeline",
          pipelineId: ctx.pipelineId,
        },
      ]);
    }

    if (!isPlainObject(raw)) {
      return loadFailure([
        {
          code: "pipeline.invalid_shape",
          message: `Invalid stage entry at index ${index} in ${declaringPath}: expected object`,
          category: "pipeline",
          pipelineId: ctx.pipelineId,
        },
      ]);
    }

    for (const key of Object.keys(raw)) {
      if (!isAllowedPipelineStageEntryKey(key)) {
        return loadFailure([
          {
            code: "pipeline.invalid_shape",
            message: `Pipeline ${ctx.pipelineId} (${ctx.path}): invalid stage entry at index ${index}: unknown key "${key}"`,
            category: "pipeline",
            pipelineId: ctx.pipelineId,
          },
        ]);
      }
    }

    const uses = typeof raw.uses === "string" ? raw.uses : undefined;
    const hasBody = hasBodyKey(raw);
    const skillOutcome = readSkill(raw);
    if (skillOutcome !== undefined && !skillOutcome.ok) {
      return skillOutcome;
    }
    const skill = skillOutcome?.ok ? skillOutcome.value : undefined;

    if (uses && hasBody) {
      return loadFailure([
        {
          code: "pipeline.stage_uses_inline_conflict",
          message: `Pipeline ${ctx.pipelineId} (${ctx.path}): stage entry at index ${index} has both uses and inline body fields`,
          category: "pipeline",
          pipelineId: ctx.pipelineId,
        },
      ]);
    }

    if (!uses && !hasBody) {
      const entryLabel = typeof raw.id === "string" ? raw.id : String(index);
      return loadFailure([
        {
          code: "pipeline.stage_missing_body",
          message: `Pipeline ${ctx.pipelineId} (${ctx.path}): stage "${entryLabel}" has no uses: path or inline body`,
          category: "pipeline",
          pipelineId: ctx.pipelineId,
        },
      ]);
    }

    let id: string | undefined = typeof raw.id === "string" && raw.id ? raw.id : undefined;
    if (!id && uses) {
      const inferred = inferIdFromUsesPath(uses);
      if (inferred) id = inferred;
    }

    if (!id) {
      return loadFailure([
        {
          code: "pipeline.invalid_shape",
          message: `Pipeline ${ctx.pipelineId} (${ctx.path}): invalid stage entry at index ${index}: id must be a non-empty string or inferrable from uses path`,
          category: "pipeline",
          pipelineId: ctx.pipelineId,
        },
      ]);
    }

    if (raw.needs !== undefined) {
      if (Array.isArray(raw.needs)) {
        return loadFailure([
          {
            code: "pipeline.dag_error",
            message: `Pipeline ${ctx.pipelineId} (${ctx.path}): stage "${id}": needs must be a string, not an array`,
            category: "pipeline",
            pipelineId: ctx.pipelineId,
          },
        ]);
      }
      if (typeof raw.needs !== "string" || !raw.needs) {
        return loadFailure([
          {
            code: "pipeline.dag_error",
            message: `Pipeline ${ctx.pipelineId} (${ctx.path}): stage "${id}": needs must be a non-empty string`,
            category: "pipeline",
            pipelineId: ctx.pipelineId,
          },
        ]);
      }
    }

    let forkValue: { select: "one" | "subset"; allow_none?: boolean } | undefined;
    if (raw.fork !== undefined) {
      if (!isPlainObject(raw.fork)) {
        return loadFailure([
          {
            code: "pipeline.dag_error",
            message: `Pipeline ${ctx.pipelineId} (${ctx.path}): stage "${id}": fork must be an object`,
            category: "pipeline",
            pipelineId: ctx.pipelineId,
          },
        ]);
      }
      forkValue = raw.fork as { select: "one" | "subset"; allow_none?: boolean };
    }

    let body: NormalizedPipelineStageEntry["body"];
    if (uses) {
      const absolutePath = path.resolve(path.dirname(declaringPath), uses);
      body = { kind: "uses", path: uses, absolutePath };
    } else {
      body = { kind: "inline", raw: extractBodyRaw(raw) };
    }

    const entry: NormalizedPipelineStageEntry = {
      id,
      declaringPath,
      body,
      ...(typeof raw.needs === "string" ? { needs: raw.needs } : {}),
      ...(forkValue !== undefined ? { fork: forkValue } : {}),
      ...(skill !== undefined ? { skill } : {}),
    };

    const priorPath = normalized.find((e) => e.id === id)?.declaringPath;
    if (priorPath) {
      return loadFailure([
        {
          code: "pipeline.include_duplicate_stage",
          message: `Duplicate stage id "${id}" in ${declaringPath} (also declared in ${priorPath})`,
          category: "pipeline",
          pipelineId: ctx.pipelineId,
        },
      ]);
    }

    normalized.push(entry);
  }

  return loadSuccess(normalized);
}

export function toWiringRefs(
  entries: NormalizedPipelineStageEntry[],
): Array<{ id: string; needs?: string; fork?: { select: "one" | "subset"; allow_none?: boolean } }> {
  return entries.map((entry) => ({
    id: entry.id,
    ...(entry.needs !== undefined ? { needs: entry.needs } : {}),
    ...(entry.fork !== undefined ? { fork: entry.fork } : {}),
  }));
}

import type { StageConfig, StageGateKind } from "./stage.js";

export type PipelineConfig = {
  id: string;
  stages: string[];
};

export type PipelineForkConfig = {
  select: "one" | "subset";
  allow_none: boolean;
};

export type PipelineStageRef = {
  id: string;
  needs?: string;
  fork?: { select: "one" | "subset"; allow_none?: boolean };
};

export type PipelineStageYamlEntry = PipelineStageRef & {
  uses?: string;
  system_prompt?: string;
  model?: string;
  payload_schema?: unknown;
  gate_kinds?: StageGateKind[];
  skill?: string;
};

export type PipelineIncludeEntry = {
  local: string;
};

export type PipelineFragmentConfig = {
  include?: PipelineIncludeEntry[];
  stages?: PipelineStageYamlEntry[];
};

export type NormalizedPipelineStageEntry = {
  id: string;
  needs?: string;
  fork?: { select: "one" | "subset"; allow_none?: boolean };
  skill?: string;
  body:
    | { kind: "inline"; raw: Record<string, unknown> }
    | { kind: "uses"; path: string; absolutePath: string };
  declaringPath: string;
};

export type PipelineStageSource =
  | { kind: "inline" }
  | { kind: "file"; path: string };

export type ResolvedPipelineStageNode = {
  id: string;
  needs: string | null;
  ancestors: string[];
  stageIndex: number;
  fork?: PipelineForkConfig;
};

export type ResolvedPipelineDag = {
  nodes: ResolvedPipelineStageNode[];
  roots: string[];
  childrenOf: Record<string, string[]>;
};

export type LoadedPipeline = {
  pipeline: PipelineConfig;
  stages: StageConfig[];
  dag: ResolvedPipelineDag;
  pipelinePath: string;
  stageSources?: Record<string, PipelineStageSource>;
};
